char *longestPalindrome(char *s) {
  int sz;
  int i, j, k, l;
  int where = 0, len = 0;

  if (!s || !*s) return s;

  sz = strlen(s);

  for (i = 0, j = 0, k = 0; len < (sz - k) * 2; i = k, j = k) {
    while (j + 1 < sz && s[j] == s[j + 1]) {
      j++; // skip all repeating characters
    }
    k = j + 1; // where to start next try
    while (i > 0 && j + 1 < sz && s[i - 1] == s[j + 1]) {
      i--; // expand dual direction
      j++;
    }
    l = j - i + 1; // what we have fond so far
    if (len < l) {
      len = l;
      where = i;
    }
  }
  char *news = (char *)malloc(sz + 1);
  memcpy(news, s + where, len);
  news[len] = 0;
  return news;
}

class Solution {
public:
  string longestPalindrome(string s) {
    if (s.empty()) return s;
    int n = s.size();
    int start = 0, maxLen = 1;

    auto expand = [&](int l, int r) {
      while (l >= 0 && r < n && s[l] == s[r]) {
        l--;
        r++;
      }
      if (r - l - 1 > maxLen) {
        maxLen = r - l - 1;
        start = l + 1;
      }
    };

    for (int i = 0; i < n; i++) {
      expand(i, i);
      expand(i, i + 1);
    }
    return s.substr(start, maxLen);
  }
};

func longestPalindrome(s string) string {
	if len(s) < 2 {
		return s
	}
	start, maxLen := 0, 1

	expand := func(l, r int) {
		for l >= 0 && r < len(s) && s[l] == s[r] {
			l--
			r++
		}
		if r-l-1 > maxLen {
			maxLen = r - l - 1
			start = l + 1
		}
	}

	for i := 0; i < len(s); i++ {
		expand(i, i)
		expand(i, i+1)
	}
	return s[start : start+maxLen]
}

class Solution {
  public String longestPalindrome(String s) {
    if (s == null || s.length() < 1) {
      return "";
    }
    int start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
      int len1 = expand(s, i, i);
      int len2 = expand(s, i, i + 1);
      int len = Math.max(len1, len2);
      if (len > end - start) {
        start = i - (len - 1) / 2;
        end = i + len / 2;
      }
    }
    return s.substring(start, end + 1);
  }

  private int expand(String s, int l, int r) {
    while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
      l--;
      r++;
    }
    return r - l - 1;
  }
}

class Solution:
    def longestPalindrome(self, s: str) -> str:
        if len(s) < 2:
            return s
        start, end = 0, 0

        def expand(l, r):
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            return r - l - 1

        for i in range(len(s)):
            length = max(expand(i, i), expand(i, i + 1))
            if length > end - start:
                start = i - (length - 1) // 2
                end = i + length // 2
        return s[start:end + 1]

impl Solution {
  pub fn longest_palindrome(s: String) -> String {
    let chars: Vec<char> = s.chars().collect();
    if chars.len() < 2 {
      return s;
    }
    let (mut start, mut end) = (0usize, 0usize);

    let expand = |mut l: i32, mut r: i32| -> i32 {
      while l >= 0 && (r as usize) < chars.len() && chars[l as usize] == chars[r as usize] {
        l -= 1;
        r += 1;
      }
      r - l - 1
    };

    for i in 0..chars.len() {
      let len = expand(i as i32, i as i32).max(expand(i as i32, i as i32 + 1));
      if len as usize > end - start {
        start = (i as i32 - (len - 1) / 2) as usize;
        end = (i as i32 + len / 2) as usize;
      }
    }
    chars[start..=end].iter().collect()
  }
}

const longestPalindrome = (s: string): string => {
  if (s.length < 2) return s;
  let start = 0;
  let end = 0;

  const expand = (l: number, r: number): number => {
    while (l >= 0 && r < s.length && s[l] === s[r]) {
      l--;
      r++;
    }
    return r - l - 1;
  };

  for (let i = 0; i < s.length; i++) {
    const len = Math.max(expand(i, i), expand(i, i + 1));
    if (len > end - start) {
      start = i - Math.floor((len - 1) / 2);
      end = i + Math.floor(len / 2);
    }
  }

  return s.substring(start, end + 1);
};
